   mc.options.onboardAccessibility=false;mc.options.pauseOnLostFocus=false;mc.options.renderDistance().set(2);mc.options.simulationDistance().set(5);mc.options.framerateLimit().set(30);mc.options.guiScale().set(2);mc.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).set(.3);mc.options.save();Files.createDirectories(OUT);mc.createWorldOpenFlows().openWorld("Worldgen300",()->{});return;
