 static void equip(ServerLevel w,ServerPlayer p){out.put("prepared_inventory","vanilla netherite armor Protection IV and sword Sharpness V; inventory acquisition not tested");net.minecraft.world.item.Item[] armor={net.minecraft.world.item.Items.NETHERITE_HELMET,net.minecraft.world.item.Items.NETHERITE_CHESTPLATE,net.minecraft.world.item.Items.NETHERITE_LEGGINGS,net.minecraft.world.item.Items.NETHERITE_BOOTS};var slots=new net.minecraft.world.entity.EquipmentSlot[]{net.minecraft.world.entity.EquipmentSlot.HEAD,net.minecraft.world.entity.EquipmentSlot.CHEST,net.minecraft.world.entity.EquipmentSlot.LEGS,net.minecraft.world.entity.EquipmentSlot.FEET};for(int i=0;i<4;i++){var stack=new net.minecraft.world.item.ItemStack(armor[i]);stack.enchant(w.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.PROTECTION),4);p.setItemSlot(slots[i],stack);}var sword=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.NETHERITE_SWORD);sword.enchant(w.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.SHARPNESS),5);p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,sword);p.getInventory().setItem(1,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.BREAD,32));p.inventoryMenu.broadcastChanges();}
 static boolean load(ServerLevel w){if(load>=chunks.size())return true;var at=chunks.get(load);if(!held.contains(at)){w.getChunkSource().addRegionTicket(TICKET,at,0,300L);held.add(at);return false;}if(w.getChunkSource().getChunkNow(at.x,at.z)!=null)load++;return load>=chunks.size();}
 static boolean empty(ServerLevel w,BlockPos p){if(!w.hasChunkAt(p))return false;var s=w.getBlockState(p);return s.getFluidState().isEmpty()&&(s.getBlock() instanceof DoorBlock||s.getCollisionShape(w,p).isEmpty());}
 static boolean walk(ServerLevel w,BlockPos p){return empty(w,p)&&empty(w,p.above())&&w.getFluidState(p.below()).isEmpty()&&!w.getBlockState(p.below()).getCollisionShape(w,p.below()).isEmpty();}
 static List<BlockPos> find(ServerLevel w,BoundingBox b,BlockPos from,BlockPos to){BlockPos begin=null;for(int dy:new int[]{0,1,2,-1})if(walk(w,from.offset(0,dy,0))){begin=from.offset(0,dy,0);break;}if(begin==null)return List.of();var parent=new HashMap<Long,Long>();var queue=new ArrayDeque<BlockPos>();queue.add(begin);parent.put(begin.asLong(),begin.asLong());while(!queue.isEmpty()&&parent.size()<350000){var p=queue.removeFirst();if(p.equals(to)){var result=new ArrayList<BlockPos>();long at=p.asLong();while(true){result.add(BlockPos.of(at));long previous=parent.get(at);if(previous==at)break;at=previous;}Collections.reverse(result);return List.copyOf(result);}for(var d:List.of(Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST))for(int dy:new int[]{0,1,-1}){var q=p.relative(d).offset(0,dy,0);if(q.getX()<b.minX()-10||q.getX()>b.maxX()+10||q.getZ()<b.minZ()-10||q.getZ()>b.maxZ()+10||q.getY()<b.minY()||q.getY()>b.maxY()+8||parent.containsKey(q.asLong())||!walk(w,q)||dy==1&&!empty(w,p.above(2)))continue;parent.put(q.asLong(),p.asLong());queue.add(q);}}return List.of();}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){var mc=Minecraft.getInstance();if(done||!ready||route==null||arrived!=route.serial()||shot==route.serial()||mc.getOverlay()!=null)return;try{try(var im=Screenshot.takeScreenshot(mc.getMainRenderTarget())){im.writeToFile(OUT.resolve(label+"-"+route.serial()+"-"+route.label()+".png"));}shot=route.serial();}catch(Throwable x){finish(mc,x);}}
 static void finish(Minecraft mc,Throwable error){if(done)return;done=true;mc.options.keyUp.setDown(false);mc.options.keyJump.setDown(false);Runnable save=()->{try{if(mc.getSingleplayerServer()!=null){var w=mc.getSingleplayerServer().overworld();for(var p:held)w.getChunkSource().removeRegionTicket(TICKET,p,0,300L);}out.put("checks",checks);out.put("error",error==null?null:error.toString());out.put("elapsed_s",(System.nanoTime()-began)/1e9);out.put("status",error==null&&checks.stream().allMatch(c->c.get("status").equals("PASS"))?"PASS_SCOPED_REAL_PLAYER_WALK":"FAIL");Files.createDirectories(OUT);Files.writeString(OUT.resolve(label+"-walk.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(error!=null)error.printStackTrace();}catch(Exception x){x.printStackTrace();}mc.execute(mc::stop);};if(mc.getSingleplayerServer()!=null&&!mc.getSingleplayerServer().isSameThread())mc.getSingleplayerServer().execute(save);else save.run();}
